"""Checks if a given string is a legal pubkey generated by ssh-keygen

See https://sshref.dev
Generally, a legal key should be in 3 components, i.e.,
    A B C
where A is key type (ssh-rsa, ssh-ed25519, etc.)
      B    base64 key itself
      C    comment for the key

"""

import base64
import re


def is_pubkey(input: str) -> tuple[str, bool]:
    # Split the input into a maximum of 3 parts
    # Note that the comment may contain spaces
    parts = input.split(" ", 3)
    if len(parts) < 2:
        return "Not enough parts for key", False

    keytype = parts[0]
    key = parts[1]

    # check keytype
    match keytype:
        # check key
        case "ssh-rsa":
            if not _is_rsa_key(key):
                return "Wrong key format for rsa", False
        case "ssh-ed25519":
            if not _is_ed25519_key(key):
                return "Wrong key format for ed25519", False
        case _:
            # For now we only support rsa and ed25519:
            return "Unsupported keytype", False

    # regulate comment
    if len(parts) == 3:
        comment = _regulate_comment(parts[2])
        return f"{keytype} {key} {comment}", True
    else:
        return f"{keytype} {key}", True


def _is_rsa_key(input: str) -> bool:
    return _is_base64(input)


def _is_ed25519_key(input: str) -> bool:
    return _is_base64(input)


def _is_base64(input) -> bool:
    try:
        base64.b64decode(input, validate=True)
        return True
    except:
        return False


def _regulate_comment(comment: str) -> str:
    comment = re.sub(r"\s", " ", comment)
    comment = re.sub(r"\\", "", comment)
    comment = re.sub(r"#", "", comment)

    return comment
